//! Generate the read-op ConnectRPC surface from `shipd::services::schema::OPS`.
//!
//! Every read op (permission `*.read`) with no required args becomes a
//! `ReadOpsService` proto method + a `shipd` dispatch arm — the bulk port,
//! projected from the registry. The hand-written `account.state` locked the
//! target shape; this replaces the 50× repetition. Arg-bearing reads are a
//! later pass (they need typed request fields). Run: `cargo xtask gen-ops`.
//!
//! Outputs (committed, `@generated` — do not hand-edit):
//!   - `proto/ship/ops/v1/reads.gen.proto`     (ReadOpsService + request msgs)
//!   - `apps/shipd/src/ops_reads_gen.rs`       (`impl ReadOpsService for OpsImpl`)

use std::fmt::Write as _;
use std::path::PathBuf;

use anyhow::{Context, Result};

struct ReadOp {
    /// Registry op name, e.g. `account.state`.
    op: String,
    /// Proto method name, e.g. `AccountState`.
    method: String,
    /// Generated trait method (connectrpc snake-cases the proto name).
    snake: String,
    /// Required capability string (the op's `permission`).
    capability: String,
}

/// PascalCase a dotted/underscored op name: `agents.permission_presets`
/// → `AgentsPermissionPresets`.
fn pascal(op: &str) -> String {
    op.split(['.', '_'])
        .map(|seg| {
            let mut chars = seg.chars();
            match chars.next() {
                Some(first) => first.to_uppercase().chain(chars).collect::<String>(),
                None => String::new(),
            }
        })
        .collect()
}

fn collect() -> Vec<ReadOp> {
    let mut out = Vec::new();
    for op in shipd::services::schema::OPS {
        if !op.permission.ends_with(".read") {
            continue; // commands get typed messages, not the JSON bridge
        }
        if op.args.iter().any(|a| a.required) {
            continue; // arg-bearing reads: later typed-request pass
        }
        out.push(ReadOp {
            op: op.name.to_string(),
            method: pascal(op.name),
            snake: op.name.replace('.', "_"),
            capability: op.permission.to_string(),
        });
    }
    out
}

fn render_proto(ops: &[ReadOp]) -> String {
    let mut s = String::new();
    s.push_str(
        "// @generated by `cargo xtask gen-ops` from shipd::services::schema::OPS.\n\
         // Do not hand-edit — re-run the generator. Read ops projected onto Connect:\n\
         // each carries its proto policy options; the body is the registry JSON\n\
         // (JsonResponse), the impl delegates to services::registry::call.\n\
         syntax = \"proto3\";\n\n\
         package ship.ops.v1;\n\n\
         import \"ship/ops/v1/policy.proto\";\n\
         import \"ship/ops/v1/ops.proto\";\n\n\
         service ReadOpsService {\n",
    );
    for o in ops {
        let _ = write!(
            s,
            "  rpc {m}({m}Request) returns (JsonResponse) {{\n    \
             option (ship.ops.v1.capability) = \"{cap}\";\n    \
             option (ship.ops.v1.blast_radius) = BLAST_RADIUS_C0_SAFE;\n  }}\n",
            m = o.method,
            cap = o.capability,
        );
    }
    s.push_str("}\n\n");
    for o in ops {
        let _ = write!(s, "message {m}Request {{}}\n", m = o.method);
    }
    s
}

fn render_rust(ops: &[ReadOp]) -> String {
    let mut s = String::new();
    s.push_str(
        "// @generated by `cargo xtask gen-ops` from shipd::services::schema::OPS.\n\
         // Do not hand-edit. Included from ops_rpc.rs; OpsImpl + dispatch_json are\n\
         // in scope there. Each read op delegates to the registry via dispatch_json.\n\
         #[allow(refining_impl_trait)]\n\
         impl ::ship_ops_rpc::ReadOpsService for OpsImpl {\n",
    );
    for o in ops {
        let _ = write!(
            s,
            "    async fn {snake}(\n        &self,\n        \
             _ctx: ::connectrpc::RequestContext,\n        \
             _req: ::ship_ops_rpc::Owned{m}RequestView,\n    ) -> \
             ::connectrpc::ServiceResult<::ship_ops_rpc::JsonResponse> {{\n        \
             self.dispatch_json(\"{op}\")\n    }}\n",
            snake = o.snake,
            m = o.method,
            op = o.op,
        );
    }
    s.push_str("}\n");
    s
}

pub fn run() -> Result<()> {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");
    let ops = collect();

    let proto_path = root.join("proto/ship/ops/v1/reads.gen.proto");
    std::fs::write(&proto_path, render_proto(&ops))
        .with_context(|| format!("writing {}", proto_path.display()))?;

    let rust_path = root.join("apps/shipd/src/ops_reads_gen.rs");
    std::fs::write(&rust_path, render_rust(&ops))
        .with_context(|| format!("writing {}", rust_path.display()))?;

    eprintln!(
        "gen-ops: {} read ops → {} + {}",
        ops.len(),
        proto_path.display(),
        rust_path.display()
    );
    Ok(())
}
